/** A March birth that works out, today, as the given school year, so the tests don't age every September. */
const bornInYear = (schoolYear: number) => {
  const today = new Date();
  const thisYear = today.getUTCFullYear();
  for (let birthYear = thisYear - 20; birthYear <= thisYear; birthYear += 1) {
    const birth = { birthMonth: 3, birthYear, yearGroupAdjustment: 0 } as const;
    if (findSchoolYear(birth, today) === schoolYear) {
      return birth;
    }
  }
  throw new Error(
    `no March birth works out as school year ${String(schoolYear)}`,
  );
};

