const gatedAppDatabasePassword = "the-gated-runs-app-database-password";

/** The app's own login on the database the owner's URL names, as migrate sets it up: wizzaroo_app, never the owner. */
const buildAppDatabaseUrl = (ownerUrl: string): string => {
  const appUrl = new URL(ownerUrl);
  appUrl.username = appLoginRole;
  appUrl.password = gatedAppDatabasePassword;
  return appUrl.href;
};

/** Migrates as the owner, as the migrate command does, then opens the app's own connections, which a server runs on. */
const openAppDatabase = async (ownerUrl: string): Promise<Database> => {
  const appUrl = buildAppDatabaseUrl(ownerUrl);
  await migrateDatabase(ownerUrl, appUrl);
  return openDatabase(appUrl);
};

const endDatabase = async (database: Database): Promise<void> => {
  await Promise.all(listPools(database).map((pool) => pool.end()));
};

/** Runs set-up only the tables' owner may do, such as emptying the Audit Log, on an owner's connection it then ends. */
const runAsTheOwner = async <Result>(
  ownerUrl: string,
  work: (ownerDatabase: Database) => Promise<Result>,
): Promise<Result> => {
  const ownerDatabase = openOwnerDatabase(ownerUrl);
  try {
    return await work(ownerDatabase);
  } finally {
    await endDatabase(ownerDatabase);
  }
};

// TOTP secrets are kept sealed under TOTP_SECRET_KEY (#254); the suite's servers read the test key from vitest's env.
const testTotpSecretKey = loadTotpSecretKey();

/** The secret as issued, from a sealed totp_secrets.secret or totp_setups.secret as stored; throws if it doesn't open. */
const openStoredTotpSecret = (userId: string, sealedSecret: string): string => {
  const secret = openTotpSecret(testTotpSecretKey, { userId, sealedSecret });
  if (secret === undefined) {
    throw new Error(`the stored TOTP secret of ${userId} doesn't open`);
  }
  return secret;
};

const sealTestTotpSecret = (userId: string, secret: string): string =>
  sealTotpSecret(testTotpSecretKey, { userId, secret });

/** Whether a stored recovery code hash is one of the codes, as the server checks it (#255). */
const findRecoveryCodesMatching = async (
  codeHash: string,
  codes: readonly string[],
): Promise<string[]> => {
  const matches = await Promise.all(
    codes.map((code) => isRecoveryCodeRight(codeHash, code)),
  );
  return codes.filter((_, index) => matches[index]);
};

