interface EmailPlatformSend {
  authorization: string | null;
  to: string[];
  templateSlug: string;
  variables: Record<string, unknown>;
}

const isEmailPlatformSend = (
  value: unknown,
): value is Omit<EmailPlatformSend, "authorization"> =>
  typeof value === "object" &&
  value !== null &&
  "to" in value &&
  Array.isArray(value.to) &&
  "templateSlug" in value &&
  typeof value.templateSlug === "string" &&
  "variables" in value &&
  typeof value.variables === "object";

/**
 * Stands in for the email platform's API, as the pen-test deployment's stand-in does: it takes each send through the
 * real email client, keeps it, and answers that it is queued.
 */
const buildEmailPlatformStandIn = () => {
  const sends: EmailPlatformSend[] = [];
  const fetch: typeof globalThis.fetch = (_input, init) => {
    const body: unknown = JSON.parse(
      typeof init?.body === "string" ? init.body : "",
    );
    if (!isEmailPlatformSend(body)) {
      throw new Error("the email client sent something unexpected");
    }
    sends.push({
      ...body,
      authorization: new Headers(init?.headers).get("Authorization"),
    });
    return Promise.resolve(
      Response.json(
        { id: randomUUID(), status: "queued", to: body.to },
        { status: 202 },
      ),
    );
  };
  return {
    sends,
    sendEmail: buildEmailSender(
      createEmailPlatformClient(
        {
          baseUrl: new URL("https://mail.wizzaroo.example"),
          apiKey: "ek_the-integration-tests-key",
        },
        fetch,
      ),
    ),
  };
};

