const readFamilyExport = (value: unknown): Record<string, unknown[]> => {
  if (typeof value !== "object" || value === null) {
    throw new Error("the API answered with something other than an export");
  }
  return Object.fromEntries(
    Object.entries(value).map(([table, rows]: [string, unknown]) => {
      if (!Array.isArray(rows)) {
        throw new Error(`the export's ${table} isn't a list of rows`);
      }
      return [table, rows];
    }),
  );
};

type CborValue = Parameters<typeof isoCBOR.encode>[0];

const authenticatorFlags = {
  userPresent: 0x01,
  userVerified: 0x04,
  attestedCredentialData: 0x40,
} as const;

const verifiedUserFlags =
  authenticatorFlags.userPresent | authenticatorFlags.userVerified;

const coseKey = {
  keyType: 1,
  algorithm: 3,
  curve: -1,
  x: -2,
  y: -3,
} as const;

const coseEllipticCurveKeyType = 2;
const coseEs256Algorithm = -7;
const coseP256Curve = 1;

const sha256 = (data: Uint8Array): Buffer =>
  createHash("sha256").update(data).digest();

const buildSoftAuthenticator = (origin: URL) => {
  const { privateKey, publicKey } = generateKeyPairSync("ec", {
    namedCurve: "P-256",
  });
  const { x, y } = publicKey.export({ format: "jwk" });
  if (x === undefined || y === undefined) {
    throw new Error("the P-256 key has no coordinates");
  }
  const credentialIdBytes = randomBytes(16);
  const credentialId = isoBase64URL.fromBuffer(credentialIdBytes);
  let signCount = 0;

  const buildClientDataJSON = (type: string, challenge: string): string =>
    isoBase64URL.fromUTF8String(
      JSON.stringify({
        type,
        challenge,
        origin: origin.origin,
        crossOrigin: false,
      }),
    );

  const buildAuthenticatorData = (
    flags: number,
    attestedCredentialData: Uint8Array = new Uint8Array(),
  ): Uint8Array<ArrayBuffer> => {
    const counter = Buffer.alloc(4);
    counter.writeUInt32BE(signCount);
    return new Uint8Array(
      Buffer.concat([
        sha256(Buffer.from(origin.hostname)),
        Buffer.from([flags]),
        counter,
        attestedCredentialData,
      ]),
    );
  };

  const register = (
    challenge: string,
    flags: number = verifiedUserFlags,
  ): RegistrationResponseJSON => {
    const cosePublicKey = isoCBOR.encode(
      new Map<string | number, CborValue>([
        [coseKey.keyType, coseEllipticCurveKeyType],
        [coseKey.algorithm, coseEs256Algorithm],
        [coseKey.curve, coseP256Curve],
        [coseKey.x, isoBase64URL.toBuffer(x)],
        [coseKey.y, isoBase64URL.toBuffer(y)],
      ]),
    );
    const credentialIdLength = Buffer.alloc(2);
    credentialIdLength.writeUInt16BE(credentialIdBytes.length);
    const attestedCredentialData = Buffer.concat([
      Buffer.alloc(16),
      credentialIdLength,
      credentialIdBytes,
      cosePublicKey,
    ]);
    const attestationObject = isoCBOR.encode(
      new Map<string | number, CborValue>([
        ["fmt", "none"],
        ["attStmt", new Map()],
        [
          "authData",
          buildAuthenticatorData(
            flags | authenticatorFlags.attestedCredentialData,
            attestedCredentialData,
          ),
        ],
      ]),
    );
    return {
      id: credentialId,
      rawId: credentialId,
      type: "public-key",
      response: {
        clientDataJSON: buildClientDataJSON("webauthn.create", challenge),
        attestationObject: isoBase64URL.fromBuffer(attestationObject),
        transports: ["internal"],
      },
      clientExtensionResults: {},
    };
  };

  const signIn = (
    challenge: string,
    flags: number = verifiedUserFlags,
  ): AuthenticationResponseJSON => {
    signCount += 1;
    const authenticatorData = buildAuthenticatorData(flags);
    const clientDataJSON = buildClientDataJSON("webauthn.get", challenge);
    const signature = sign(
      "sha256",
      Buffer.concat([
        authenticatorData,
        sha256(isoBase64URL.toBuffer(clientDataJSON)),
      ]),
      privateKey,
    );
    return {
      id: credentialId,
      rawId: credentialId,
      type: "public-key",
      response: {
        clientDataJSON,
        authenticatorData: isoBase64URL.fromBuffer(authenticatorData),
        signature: isoBase64URL.fromBuffer(new Uint8Array(signature)),
      },
      clientExtensionResults: {},
    };
  };

  return { credentialId, register, signIn };
};

const readChallenge = (value: unknown): string => {
  if (
    typeof value !== "object" ||
    value === null ||
    !("challenge" in value) ||
    typeof value.challenge !== "string"
  ) {
    throw new Error("the API answered without a passkey challenge");
  }
  return value.challenge;
};

const readRecoveryCodes = (value: unknown): string[] => {
  if (
    typeof value !== "object" ||
    value === null ||
    !("recoveryCodes" in value) ||
    !Array.isArray(value.recoveryCodes) ||
    !value.recoveryCodes.every((code) => typeof code === "string")
  ) {
    throw new Error("the API answered without recovery codes");
  }
  return value.recoveryCodes;
};

