const findFreePort = async (): Promise<number> => {
  const probe = createServer().listen(0, "127.0.0.1");
  await once(probe, "listening");
  const address = probe.address();
  probe.close();
  if (address === null || typeof address === "string") {
    throw new Error("the port probe did not listen on TCP");
  }
  return address.port;
};

/**
 * The probes of how a failing query is answered and logged used to reach one
 * with a NUL byte, which Postgres refuses in `text` (`22021`). Since #294 a NUL
 * byte is refused with a 400 above the database, so they make Postgres refuse
 * a query on purpose instead: here every insert and update on one table, with
 * the same code, while `run` runs.
 */
const whilePostgresRefusesWritesTo = async <Result>(
  ownerUrl: string,
  table: string,
  run: () => Promise<Result>,
): Promise<Result> => {
  // Only the tables' owner may add a trigger, and the app no longer logs in as it (#273).
  const database = openOwnerDatabase(ownerUrl);
  const trigger = sql.identifier(`pen_test_refuse_writes_to_${table}`);
  await database.execute(sql`
    create or replace function pen_test_refuse_write() returns trigger
    language plpgsql as $$
    begin
      raise exception 'pen test: Postgres refuses this write'
        using errcode = '22021';
    end
    $$
  `);
  await database.execute(
    sql`create trigger ${trigger} before insert or update on ${sql.identifier(table)} for each row execute function pen_test_refuse_write()`,
  );
  try {
    return await run();
  } finally {
    await database.execute(
      sql`drop trigger ${trigger} on ${sql.identifier(table)}`,
    );
    await database.execute(sql`drop function pen_test_refuse_write()`);
    await endDatabase(database);
  }
};

/**
 * As `whilePostgresRefusesWritesTo`, for a read: the column is renamed while
 * `run` runs, so every query the app builds that names it fails (`42703`).
 */
const whilePostgresLacksColumn = async <Result>(
  ownerUrl: string,
  table: string,
  column: string,
  run: () => Promise<Result>,
): Promise<Result> => {
  // Only the tables' owner may rename a column, and the app no longer logs in as it (#273).
  const database = openOwnerDatabase(ownerUrl);
  const hiddenColumn = `pen_test_hidden_${column}`;
  await database.execute(
    sql`alter table ${sql.identifier(table)} rename column ${sql.identifier(column)} to ${sql.identifier(hiddenColumn)}`,
  );
  try {
    return await run();
  } finally {
    await database.execute(
      sql`alter table ${sql.identifier(table)} rename column ${sql.identifier(hiddenColumn)} to ${sql.identifier(column)}`,
    );
    await endDatabase(database);
  }
};

const joinAnswerLines = (answers: string[]): string =>
  answers.map((answer) => `${answer}\n`).join("");

const buildAnsweringTerminal = (answers: string[]) => {
  let outputText = "";
  const output = new Writable({
    write: (chunk: Buffer | string, _encoding, callback) => {
      outputText += chunk.toString();
      callback();
    },
  });
  return {
    input: Readable.from([joinAnswerLines(answers)]),
    output,
    getOutputText: () => outputText,
  };
};

