const runSeedOwnerCommand = async (
  answers: string[],
): Promise<SeedOwnerRun> => {
  const seedOwner = spawn(
    process.execPath,
    ["--import", "tsx", "src/server/index.ts", "seed-owner"],
    { stdio: ["pipe", "pipe", "pipe"] },
  );
  let stdout = "";
  let stderr = "";
  seedOwner.stdout.on("data", (chunk: Buffer) => {
    stdout += chunk.toString();
  });
  seedOwner.stderr.on("data", (chunk: Buffer) => {
    stderr += chunk.toString();
  });
  seedOwner.stdin.end(joinAnswerLines(answers));
  await once(seedOwner, "close");
  return { exitCode: seedOwner.exitCode, stdout, stderr };
};

const routeMethods = [
  "DELETE",
  "GET",
  "HEAD",
  "OPTIONS",
  "PATCH",
  "POST",
  "PUT",
] as const;

type RouteMethod = (typeof routeMethods)[number];

const isRouteMethod = (method: string): method is RouteMethod =>
  routeMethods.some((routeMethod) => routeMethod === method);

interface ServerRoute {
  method: RouteMethod;
  path: string;
}

const routeTreeIndentWidth = 4;

const listServerRoutes = (server: FastifyInstance): ServerRoute[] => {
  const pathSegmentsByDepth: string[] = [];
  return server
    .printRoutes({ commonPrefix: false })
    .split("\n")
    .flatMap((line) => {
      const match = /^(.*?)[├└]── (\S+)(?: \(([^)]+)\))?$/.exec(line);
      if (match === null) {
        return [];
      }
      const [, indent, pathSegment] = match;
      const methods = match.at(3);
      pathSegmentsByDepth.splice(
        indent.length / routeTreeIndentWidth,
        Infinity,
        pathSegment,
      );
      if (methods === undefined) {
        return [];
      }
      const path = pathSegmentsByDepth.join("");
      return methods.split(", ").map((method) => {
        if (!isRouteMethod(method)) {
          throw new Error(
            `the server has a route with an unknown method, ${method}`,
          );
        }
        return { method, path: path === "*" ? "/" : path };
      });
    });
};

