    describe("the cohort moving on 1 September", () => {
      const septemberYear =
        probePlan.day.getUTCMonth() >= 8
          ? probePlan.day.getUTCFullYear() + 1
          : probePlan.day.getUTCFullYear();
      const lastMinuteOfAugust = new Date(
        Date.UTC(septemberYear, 7, 31, 22, 59),
      );
      const firstMinuteOfSeptember = new Date(
        Date.UTC(septemberYear, 7, 31, 23, 0),
      );

      const fetchSeenAt = async (moment: Date) => {
        vi.setSystemTime(moment);
        const seen: Record<string, unknown> = {};
        for (const handle of probeTeacherHandles) {
          seen[handle] = {
            api: await fetchSeenByApi(handle),
            policies: await fetchSeenByPolicies(handle),
          };
        }
        return seen;
      };

      const buildExpectedSeen = (
        reaches: Record<ProbeTeacherHandle, TeacherReach>,
      ) =>
        Object.fromEntries(
          probeTeacherHandles.map((handle) => {
            const { childIds, parentIds } = reaches[handle];
            return [
              handle,
              {
                api: { childIds, parentIds },
                policies: { childIds, parentIds },
              },
            ];
          }),
        );

      it("moves every Teacher fixture's Children and Parents to the new cohort at midnight on 1 September in the UK, in the API and the policies alike", async () => {
        vi.useFakeTimers({ toFake: ["Date"] });
        try {
          const onLastMinuteOfAugust = await fetchSeenAt(lastMinuteOfAugust);
          const onFirstMinuteOfSeptember = await fetchSeenAt(
            firstMinuteOfSeptember,
          );

          expect(onLastMinuteOfAugust).toEqual(
            buildExpectedSeen(teacherReachOnLoadDay),
          );
          expect(onFirstMinuteOfSeptember).toEqual(
            buildExpectedSeen(teacherReachAfterSeptember),
          );
        } finally {
          vi.useRealTimers();
        }
      });

      it("refuses teacherAYear3 a lock on Ada once she has moved up, and keeps the lock they set before it", async () => {
        const adaId = penTestFixtureIds.childA1Year3;
        vi.useFakeTimers({ toFake: ["Date"] });
        try {
          vi.setSystemTime(lastMinuteOfAugust);
          const locked = await injectAsFixture("teacherAYear3", {
            method: "PUT",
            url: `/api/children/${adaId}/teacher-locks`,
            payload: teacherLocks,
          });
          vi.setSystemTime(firstMinuteOfSeptember);
          const unlocked = await injectAsFixture("teacherAYear3", {
            method: "PUT",
            url: `/api/children/${adaId}/teacher-locks`,
            payload: buildTeacherLocks({}),
          });

          expect(locked.statusCode).toBe(200);
          expect(unlocked.statusCode).toBe(404);
          expect(await loadStoredTeacherLocks(adaId)).toEqual(teacherLocks);
        } finally {
          vi.useRealTimers();
          await probeDatabase
            .delete(childTeacherLocks)
            .where(eq(childTeacherLocks.childId, adaId));
        }
      });
    });

