    describe("a Parent giving Stars from the Awards page", () => {
      const setUpRewardedChild = async (email: string, nickname: string) => {
        const { userId, familyId } = await insertSchoolParent(
          email,
          hillsideId,
        );
        const childId = await addSchoolChild(
          familyId,
          hillsideId,
          nickname,
          bornInYear(2),
        );
        await database
          .insert(characters)
          .values({ childId, name: `${nickname}'s Character` });
        return {
          userId,
          familyId,
          childId,
          token: await signIn(email, parentPassword),
        };
      };

      const giveStarsAs = (token: string, childId: string, stars: number) =>
        injectAs(token, {
          method: "POST",
          url: `/api/children/${childId}/star-awards`,
          payload: { stars },
        });

      it("gives a Parent's own Child 5, 10 or 15 Stars at a time, at most 15 a day, and shows the Child's Stars, Family Chest and Quests", async () => {
        const { userId, childId, token } = await setUpRewardedChild(
          "awarding@hillside.example",
          "Goldie",
        );

        const before = await injectAs(token, {
          method: "GET",
          url: `/api/children/${childId}/awards`,
        });
        const five = await giveStarsAs(token, childId, 5);
        const ten = await giveStarsAs(token, childId, 10);
        const overTheDay = await giveStarsAs(token, childId, 5);
        const oddSizes = await Promise.all(
          [0, 1, 7, 20, 1000].map((stars) =>
            giveStarsAs(token, childId, stars),
          ),
        );

        expect(before.statusCode).toBe(200);
        expect(before.json()).toEqual({
          childId,
          stars: 0,
          starsGivenToday: 0,
          familyChestActivityCount: 0,
          questProgress: [],
        });
        expect(five.statusCode).toBe(200);
        expect(five.json()).toMatchObject({ stars: 5, starsGivenToday: 5 });
        expect(ten.statusCode).toBe(200);
        expect(ten.json()).toMatchObject({ stars: 15, starsGivenToday: 15 });
        expect(overTheDay.statusCode).toBe(409);
        expect(oddSizes.map(({ statusCode }) => statusCode)).toEqual([
          400, 400, 400, 400, 400,
        ]);
        expect(
          await database
            .select({
              stars: starAwards.stars,
              givenByParent: starAwards.givenByParent,
              awardedByUserId: starAwards.awardedByUserId,
            })
            .from(starAwards)
            .where(eq(starAwards.childId, childId))
            .orderBy(starAwards.stars),
        ).toEqual([
          { stars: 5, givenByParent: true, awardedByUserId: userId },
          { stars: 10, givenByParent: true, awardedByUserId: userId },
        ]);
      });

      it("counts neither the Admin's Stars nor a Parent's from an earlier day towards today's 15", async () => {
        const { childId, token } = await setUpRewardedChild(
          "yesterday@hillside.example",
          "Sunny",
        );
        await giveStarsAs(token, childId, 15);

        const byAdmin = await injectAs(await signInAdmin(), {
          method: "POST",
          url: `/api/admin/children/${childId}/star-awards`,
          payload: { stars: 40 },
        });
        const afterAdmin = await injectAs(token, {
          method: "GET",
          url: `/api/children/${childId}/awards`,
        });
        await database
          .update(starAwards)
          .set({ awardedAt: sql`now() - interval '2 days'` })
          .where(
            and(
              eq(starAwards.childId, childId),
              eq(starAwards.givenByParent, true),
            ),
          );
        const nextDay = await giveStarsAs(token, childId, 15);

        expect(byAdmin.statusCode).toBe(204);
        expect(afterAdmin.json()).toMatchObject({
          stars: 55,
          starsGivenToday: 15,
        });
        expect(nextDay.statusCode).toBe(200);
        expect(nextDay.json()).toMatchObject({
          stars: 70,
          starsGivenToday: 15,
        });
      });

      it("gives no more than 15 Stars a day when a Child's Parents give them at the same moment", async () => {
        const { childId, token } = await setUpRewardedChild(
          "at-once@hillside.example",
          "Twinkle",
        );

        const answers = await Promise.all(
          [10, 10, 10, 10].map((stars) => giveStarsAs(token, childId, stars)),
        );

        expect(answers.map(({ statusCode }) => statusCode).toSorted()).toEqual([
          200, 409, 409, 409,
        ]);
        const [given] = await database
          .select({ stars: sql<number>`sum(${starAwards.stars})::integer` })
          .from(starAwards)
          .where(eq(starAwards.childId, childId));
        expect(given.stars).toBe(10);
      });

      it("finds no Child outside the Parent's own Family, and refuses a Teacher", async () => {
        const own = await setUpRewardedChild("own@hillside.example", "Glimmer");
        const other = await setUpRewardedChild(
          "other@hillside.example",
          "Sparky",
        );
        await insertTeacher("awards-year2@hillside.example", hillsideId, [2]);
        const teacherToken = await signInTeacher(
          "awards-year2@hillside.example",
        );

        const answers = {
          otherGet: await injectAs(own.token, {
            method: "GET",
            url: `/api/children/${other.childId}/awards`,
          }),
          otherPost: await giveStarsAs(own.token, other.childId, 5),
          noSuchChild: await giveStarsAs(own.token, randomUUID(), 5),
          teacherGet: await injectAs(teacherToken, {
            method: "GET",
            url: `/api/children/${own.childId}/awards`,
          }),
          teacherPost: await giveStarsAs(teacherToken, own.childId, 5),
          signedOut: await server.inject({
            method: "POST",
            url: `/api/children/${own.childId}/star-awards`,
            payload: { stars: 5 },
          }),
        };

        expect(
          Object.fromEntries(
            Object.entries(answers).map(([name, { statusCode }]) => [
              name,
              statusCode,
            ]),
          ),
        ).toEqual({
          otherGet: 404,
          otherPost: 404,
          noSuchChild: 404,
          teacherGet: 403,
          teacherPost: 403,
          signedOut: 401,
        });
        expect(
          await database
            .select({ id: starAwards.id })
            .from(starAwards)
            .where(inArray(starAwards.childId, [own.childId, other.childId])),
        ).toEqual([]);
      });

      it("lets a Parent's reach write only their own award of 5, 10 or 15 Stars to their own Child", async () => {
        const own = await setUpRewardedChild(
          "reach-own@hillside.example",
          "Comet",
        );
        const other = await setUpRewardedChild(
          "reach-other@hillside.example",
          "Nova",
        );
        const parentReach: CallerReach = {
          userId: own.userId,
          familyId: own.familyId,
          isAdmin: false,
          isOwnFamilyOnly: true,
        };
        const deviceReach: CallerReach = {
          userId: null,
          familyId: own.familyId,
          isAdmin: false,
        };
        const insertAs = (
          reach: CallerReach,
          award: Partial<typeof starAwards.$inferInsert>,
        ) =>
          runWithinReach(database, reach, (reachDatabase) =>
            reachDatabase.insert(starAwards).values({
              childId: own.childId,
              stars: 5,
              awardedByUserId: own.userId,
              givenByParent: true,
              ...award,
            }),
          );

        // Each insert starts only once it is awaited: started together, those refused before their turn
        // were unhandled rejections.
        const refusals = [
          () => insertAs(parentReach, { stars: 7 }),
          () => insertAs(parentReach, { stars: 1000 }),
          () => insertAs(parentReach, { givenByParent: false }),
          () => insertAs(parentReach, { awardedByUserId: other.userId }),
          () => insertAs(parentReach, { awardedByUserId: null }),
          () => insertAs(parentReach, { childId: other.childId }),
          () => insertAs(deviceReach, {}),
        ];

        for (const refusal of refusals) {
          await expect(refusal()).rejects.toMatchObject({
            cause: { code: "42501" },
          });
        }
        await insertAs(parentReach, { stars: 15 });
        expect(
          await database
            .select({ stars: starAwards.stars })
            .from(starAwards)
            .where(inArray(starAwards.childId, [own.childId, other.childId])),
        ).toEqual([{ stars: 15 }]);
      });
    });

    describe("a second factor for Teachers and the Admin", () => {
      it("keeps a Teacher with only a password away from every School's data until they set up two-factor authentication", async () => {
        const email = "password-only@hillside.example";
        const userId = await insertTeacher(email, hillsideId, [2]);
        const token = await signIn(email, teacherPassword);

        const blocked = await Promise.all(
          ["/api/school-children", "/api/parents", "/api/schools"].map((url) =>
            injectAs(token, { method: "GET", url }),
          ),
        );
        const me = await injectAs(token, { method: "GET", url: "/api/me" });
        await injectAs(token, { method: "POST", url: "/api/totp-setups" });
        const [{ secret }] = await database
          .select({ secret: totpSetups.secret })
          .from(totpSetups)
          .where(eq(totpSetups.userId, userId));
        const turnedOn = await injectAs(token, {
          method: "POST",
          url: "/api/two-factor",
          payload: {
            code: buildTotpCode(
              openStoredTotpSecret(userId, secret),
              getTotpStep(new Date()),
            ),
          },
        });
        const unblocked = await injectAs(token, {
          method: "GET",
          url: "/api/school-children",
        });

        expect(blocked.map(({ statusCode }) => statusCode)).toEqual([
          403, 403, 403,
        ]);
        expect(blocked[0].json()).toMatchObject({
          code: "second-factor-required",
        });
        expect(me.json()).toMatchObject({
          roles: ["teacher"],
          needsSecondFactor: true,
        });
        expect(turnedOn.statusCode).toBe(201);
        expect(unblocked.statusCode).toBe(200);
      });

      it("keeps the Admin away from Families' data, their own included, until they sign in with a second factor", async () => {
        const token = await signIn(owner.email, owner.password);

        const responses = await Promise.all(
          ["/api/children", "/api/teachers", "/api/family"].map((url) =>
            injectAs(token, { method: "GET", url }),
          ),
        );

        expect(responses.map(({ statusCode }) => statusCode)).toEqual([
          403, 403, 403,
        ]);
      });

      it("lets a Teacher who signed in with a password prove it with a passkey they already have, but not with someone else's", async () => {
        const email = "passkey-holder@hillside.example";
        const userId = await insertTeacher(email, hillsideId, [4]);
        const teachersLaptop = buildSoftAuthenticator(publicUrl);
        const strangersLaptop = buildSoftAuthenticator(publicUrl);
        const fetchChallenge = async (token: string, url: string) =>
          readChallenge(
            (await injectAs(token, { method: "POST", url })).json<unknown>(),
          );
        const addPasskey = async (
          token: string,
          authenticator: typeof teachersLaptop,
        ) => {
          const added = await injectAs(token, {
            method: "POST",
            url: "/api/passkeys",
            payload: {
              name: "Laptop",
              response: authenticator.register(
                await fetchChallenge(
                  token,
                  "/api/passkey-registration-options",
                ),
              ),
            },
          });
          expect(added.statusCode).toBe(201);
        };
        await addPasskey(await signIn(email, teacherPassword), teachersLaptop);
        const strangerEmail = "stranger@hillside.example";
        await insertTeacher(strangerEmail, hillsideId, [5]);
        await addPasskey(
          await signIn(strangerEmail, teacherPassword),
          strangersLaptop,
        );
        const token = await signIn(email, teacherPassword);
        const confirmWith = async (authenticator: typeof teachersLaptop) =>
          injectAs(token, {
            method: "POST",
            url: "/api/passkey-confirmations",
            payload: {
              response: authenticator.signIn(
                await fetchChallenge(
                  token,
                  "/api/passkey-confirmation-options",
                ),
              ),
            },
          });

        const blocked = await injectAs(token, {
          method: "GET",
          url: "/api/school-children",
        });
        const withStrangersPasskey = await confirmWith(strangersLaptop);
        const stillBlocked = await injectAs(token, {
          method: "GET",
          url: "/api/school-children",
        });
        const withOwnPasskey = await confirmWith(teachersLaptop);
        const unblocked = await injectAs(token, {
          method: "GET",
          url: "/api/school-children",
        });

        expect(blocked.statusCode).toBe(403);
        expect(withStrangersPasskey.statusCode).toBe(401);
        expect(stillBlocked.statusCode).toBe(403);
        expect(withOwnPasskey.statusCode).toBe(204);
        expect(unblocked.statusCode).toBe(200);
        const [passkeyRow] = await database
          .select({ lastUsedAt: passkeys.lastUsedAt })
          .from(passkeys)
          .where(eq(passkeys.userId, userId));
        expect(passkeyRow.lastUsedAt).not.toBeNull();
      });

      it("has no passkey to ask for when the Admin has none", async () => {
        const response = await injectAs(
          await signIn(owner.email, owner.password),
          { method: "POST", url: "/api/passkey-confirmation-options" },
        );

        expect(response.statusCode).toBe(404);
      });

      it("leaves two-factor authentication optional for Parents", async () => {
        const { familyId } = await insertSchoolParent(
          "optional@example.com",
          hillsideId,
        );
        const token = await signIn("optional@example.com", parentPassword);

        const family = await injectAs(token, {
          method: "GET",
          url: "/api/children",
        });
        const me = await injectAs(token, { method: "GET", url: "/api/me" });

        expect(familyId).toBeDefined();
        expect(family.statusCode).toBe(200);
        expect(me.json()).toMatchObject({ needsSecondFactor: false });
      });
    });

