      it("copies an Invite as a link without emailing it, refuses it once expired, and replaces it when resent", async () => {
        const adminToken = await signInAdmin();
        sentEmails.length = 0;

        const created = await injectAs(adminToken, {
          method: "POST",
          url: "/api/parents",
          payload: {
            name: "Linky",
            email: "linky@example.com",
            schoolId: hillsideId,
            invite: "link",
          },
        });
        const { userId, invite } = readCreatedPerson(created.json());
        const emailedWhenCreated = sentEmails.length;
        await database
          .update(invites)
          .set({ expiresAt: sql`now() - interval '1 second'` })
          .where(eq(invites.id, invite.id));
        const expired = await server.inject({
          method: "POST",
          url: "/api/invite-acceptances",
          payload: {
            token: readInviteToken(invite.url),
            password: parentPassword,
          },
        });
        const resent = await injectAs(adminToken, {
          method: "POST",
          url: `/api/people/${userId}/invites`,
          payload: { invite: "email" },
        });
        const fresh = await server.inject({
          method: "POST",
          url: "/api/invite-acceptances",
          payload: {
            token: readInviteToken(resent.json<{ url: string }>().url),
            password: parentPassword,
          },
        });

        expect(emailedWhenCreated).toBe(0);
        expect(expired.statusCode).toBe(404);
        expect(resent.statusCode).toBe(201);
        expect(fresh.statusCode).toBe(204);
        expect(sentEmails.map(({ template }) => template)).toEqual([
          "parentInvite",
        ]);
      });

