      it("keeps a Teacher's next adult for a Family out of it, with no Invite, until one of its Parents agrees, then emails the Invite to the address that Parent saw", async () => {
        await insertTeacher("asker@hillside.example", hillsideId, [3]);
        const first = await insertSchoolParent(
          "household-first@example.com",
          hillsideId,
        );
        const teacherToken = await signInTeacher("asker@hillside.example");
        sentEmails.length = 0;
        const askAs = (invite: "link" | "email") =>
          injectAs(teacherToken, {
            method: "POST",
            url: "/api/parents",
            payload: {
              name: "Household Second",
              email: "household-second@example.com",
              familyId: first.familyId,
              invite,
            },
          });
        const loadFamilyLinks = (userId: string) =>
          database
            .select({
              userId: familyParents.userId,
              familyId: familyParents.familyId,
            })
            .from(familyParents)
            .where(eq(familyParents.userId, userId));
        const resendAs = (token: string, userId: string, invite: string) =>
          injectAs(token, {
            method: "POST",
            url: `/api/people/${userId}/invites`,
            payload: { invite },
          });

        const asLink = await askAs("link");
        const asked = await askAs("email");
        const { userId } = asked.json<{ userId: string }>();
        const linksBeforeAgreement = await loadFamilyLinks(userId);
        const invitesBeforeAgreement = await database
          .select({ id: invites.id })
          .from(invites)
          .where(eq(invites.userId, userId));
        const resentBeforeAgreement = await resendAs(
          teacherToken,
          userId,
          "email",
        );
        const emailsBeforeAgreement = sentEmails.map(({ to, template }) => ({
          to,
          template,
        }));
        const parentToken = await signIn(
          "household-first@example.com",
          parentPassword,
        );
        const waiting = await injectAs(parentToken, {
          method: "GET",
          url: "/api/family-join-requests",
        });
        const agreed = await injectAs(parentToken, {
          method: "PUT",
          url: `/api/family-join-requests/${userId}/agreement`,
        });
        const linkAfterAgreement = await resendAs(teacherToken, userId, "link");
        const emailAfterAgreement = await resendAs(
          teacherToken,
          userId,
          "email",
        );
        const linkFromTheAdmin = await resendAs(
          await signInAdmin(),
          userId,
          "link",
        );

        expect(asLink.statusCode).toBe(409);
        expect(asked.statusCode).toBe(201);
        expect(asked.json()).toEqual({
          userId,
          invite: null,
          familyJoinRequest: { familyId: first.familyId },
        });
        expect(linksBeforeAgreement).toEqual([]);
        expect(invitesBeforeAgreement).toEqual([]);
        expect(resentBeforeAgreement.statusCode).toBe(409);
        expect(emailsBeforeAgreement).toEqual([
          {
            to: "household-first@example.com",
            template: "familyJoinRequest",
          },
        ]);
        expect(
          waiting
            .json<{ userId: string; name: string; email: string }[]>()
            .map(({ userId: waitingUserId, name, email }) => ({
              userId: waitingUserId,
              name,
              email,
            })),
        ).toEqual([
          {
            userId,
            name: "Household Second",
            email: "household-second@example.com",
          },
        ]);
        expect(agreed.statusCode).toBe(204);
        expect(await loadFamilyLinks(userId)).toEqual([
          { userId, familyId: first.familyId },
        ]);
        expect(
          sentEmails.filter(
            ({ to, template }) =>
              to === "household-second@example.com" &&
              template === "parentInvite",
          ),
        ).toHaveLength(2);
        expect(linkAfterAgreement.statusCode).toBe(409);
        expect(emailAfterAgreement.statusCode).toBe(201);
        expect(linkFromTheAdmin.statusCode).toBe(201);
      });

      it("removes a Teacher's next adult when a Parent of the Family turns them down, and lets no other Family's Parent see or answer for them", async () => {
        await insertTeacher("asker-two@hillside.example", hillsideId, [3]);
        const first = await insertSchoolParent(
          "turning-down@example.com",
          hillsideId,
        );
        await insertSchoolParent("other-household@example.com", hillsideId);
        const asked = await injectAs(
          await signInTeacher("asker-two@hillside.example"),
          {
            method: "POST",
            url: "/api/parents",
            payload: {
              name: "Unknown Adult",
              email: "unknown-adult@example.com",
              familyId: first.familyId,
              invite: "email",
            },
          },
        );
        const { userId } = asked.json<{ userId: string }>();
        const answerAs = (token: string, method: "PUT" | "DELETE") =>
          injectAs(token, {
            method,
            url:
              method === "PUT"
                ? `/api/family-join-requests/${userId}/agreement`
                : `/api/family-join-requests/${userId}`,
          });

        const otherToken = await signIn(
          "other-household@example.com",
          parentPassword,
        );
        const listedForOther = await injectAs(otherToken, {
          method: "GET",
          url: "/api/family-join-requests",
        });
        const byOther = [
          await answerAs(otherToken, "PUT"),
          await answerAs(otherToken, "DELETE"),
        ];
        const firstToken = await signIn(
          "turning-down@example.com",
          parentPassword,
        );
        const turnedDown = await answerAs(firstToken, "DELETE");
        const agreedAfterwards = await answerAs(firstToken, "PUT");
        const turnedDownEntries = await database
          .select({ actorId: auditLogEntries.actorId })
          .from(auditLogEntries)
          .where(
            and(
              eq(auditLogEntries.action, "family-join.turned-down"),
              eq(auditLogEntries.targetId, userId),
            ),
          );

        expect(asked.statusCode).toBe(201);
        expect(listedForOther.json()).toEqual([]);
        expect(byOther.map(({ statusCode }) => statusCode)).toEqual([404, 404]);
        expect(turnedDown.statusCode).toBe(204);
        expect(agreedAfterwards.statusCode).toBe(404);
        expect(
          await database
            .select({ id: users.id })
            .from(users)
            .where(eq(users.id, userId)),
        ).toEqual([]);
        expect(turnedDownEntries).toEqual([{ actorId: first.userId }]);
      });

