      const fromParent = await injectAs(parentToken, {
        method: "POST",
        url: "/api/play/events",
        payload: { playEvents: batch },
      });
      const withNoCredential = await server.inject({
        method: "POST",
        url: "/api/play/events",
        payload: { playEvents: batch },
      });

