    const fetchMastery = async (childId: string): Promise<unknown> => {
      const response = await injectAs(await signInGrace(), {
        method: "GET",
        url: "/api/children",
      });
      expect(response.statusCode).toBe(200);
      const listed: unknown = response.json();
      if (!Array.isArray(listed)) {
        throw new Error("the API answered with something other than a list");
      }
      const listedChild: unknown = listed.find(
        (candidate: unknown) =>
          typeof candidate === "object" &&
          candidate !== null &&
          "id" in candidate &&
          candidate.id === childId,
      );
      if (
        typeof listedChild !== "object" ||
        listedChild === null ||
        !("mastery" in listedChild)
      ) {
        throw new Error("the API listed the Child without their Mastery");
      }
      return listedChild.mastery;
    };

