        expect(listReachedIds(everyRow, "schools", "id")).toEqual(
          expect.arrayContaining([schoolId, otherSchoolId]),
        );
        expect(listReachedIds(everyRow, "teachers", "user_id")).toContain(
          teacherReach.userId,
        );
