      it("refuses a Teacher's session a change of email address with no proof or their password alone, refuses a sign-in with no second factor whatever it gives, and makes it with a fresh code (regression)", async () => {
        const observed = [];
        const cookiesByHandle = new Map<
          PenTestFixtureHandle,
          readonly { name: string; value: string }[]
        >();
        for (const { handle, newEmail } of staffEmailChanges) {
          const staffCookies = await signInAs(handle);
          cookiesByHandle.set(handle, staffCookies);
          const signedIn = await fetchMe(staffCookies);
          const bareSession = await askForEmailAddressCheck(
            staffCookies,
            newEmail,
          );
          const passwordAlone = await askForEmailAddressCheck(
            staffCookies,
            newEmail,
            findPasswordProof(handle),
          );
          observed.push({
            handle,
            signedIn,
            bareSession: bareSession.json<unknown>(),
            passwordAlone: passwordAlone.json<unknown>(),
            emailsSent: listEmailsSent(),
            storedEmail: (await loadAccount(handle)).email,
          });
        }
        // The same sign-in, since signing in again would spend this step's code a second time.
        const withAFreshCode = await attemptEmailChange(
          cookiesByHandle.get("teacherAYear3") ?? [],
          "teacher-a-year-3-moved@pen-test.example",
          findFreshCodeProof("teacherAYear3"),
        );

        expect(observed).toMatchObject(
          staffEmailChanges.map(({ handle }) => {
            const isPasswordOnly = handle === "teacherBYear3";
            return {
              handle,
              signedIn: {
                status: 200,
                me: { roles: ["teacher"], needsSecondFactor: isPasswordOnly },
              },
              bareSession: {
                statusCode: 403,
                code: isPasswordOnly
                  ? "second-factor-required"
                  : "account-proof-required",
              },
              passwordAlone: {
                statusCode: 403,
                code: isPasswordOnly
                  ? "second-factor-required"
                  : "second-factor-proof-required",
              },
              emailsSent: [],
              storedEmail: findFixtureEmail(handle),
            };
          }),
        );
        expect(withAFreshCode).toEqual({
          requestStatus: 204,
          confirmationStatus: 200,
        });
        expect((await loadAccount("teacherAYear3")).email).toBe(
          "teacher-a-year-3-moved@pen-test.example",
        );
      });

