    describe("what the Admin reads, and the access log", () => {
      it("serves the Admin every Child's nickname from /api/admin/families and /api/parents, and every Child's progress from /api/school-children, writing an access log row for each (regression)", async () => {
        const adminToken = await signInWithTheHarness("admin");
        const cara = findFixtureChild(penTestFixtureIds.childA2Year3);
        const responses: Awaited<ReturnType<typeof injectProbeAs>>[] = [];
        const caraRowsWritten: number[] = [];

        for (const url of childDataRoutesTheAdminReads) {
          const rowsBefore = await countAccessLogRowsFor(cara.id);
          responses.push(
            await injectProbeAs(adminToken, { method: "GET", url }),
          );
          caraRowsWritten.push(
            (await countAccessLogRowsFor(cara.id)) - rowsBefore,
          );
        }

        expect(listStatusCodes(responses)).toEqual([200, 200, 200]);
        expect(
          responses.map(
            ({ body }) =>
              body.includes(cara.id) && body.includes(cara.nickname),
          ),
        ).toEqual([true, true, true]);
        expect(caraRowsWritten).toEqual([1, 1, 1]);
      });

      it("writes an access log row for a Child each time one of those routes serves the Admin her data", async () => {
        const adminToken = await signInWithTheHarness("admin");
        const caraId = penTestFixtureIds.childA2Year3;
        const rowsWritten: number[] = [];

        for (const url of childDataRoutesTheAdminReads) {
          const rowsBefore = await countAccessLogRowsFor(caraId);
          await injectProbeAs(adminToken, { method: "GET", url });
          rowsWritten.push((await countAccessLogRowsFor(caraId)) - rowsBefore);
        }

        expect(rowsWritten).toEqual([1, 1, 1]);
      });

      it("writes exactly one access log row each time the Admin opens a Child's progress, and none for a Child who isn't there", async () => {
        const adminToken = await signInWithTheHarness("admin");
        const caraId = penTestFixtureIds.childA2Year3;
        const caraRowsBefore = await countAccessLogRowsFor(caraId);
        const allRowsBefore = await countAllAccessLogRows();

        const opened = await injectProbeAs(adminToken, {
          method: "GET",
          url: `/api/children/${caraId}/progress`,
        });
        const missing = await injectProbeAs(adminToken, {
          method: "GET",
          url: `/api/children/${randomUUID()}/progress`,
        });

        expect(listStatusCodes([opened, missing])).toEqual([200, 404]);
        expect(await countAccessLogRowsFor(caraId)).toBe(caraRowsBefore + 1);
        expect(await countAllAccessLogRows()).toBe(allRowsBefore + 1);
      });
    });

    describe("the Admin deleting a Family or a Child no one asked to delete", () => {
      const askForDeletionInProbe = async (
        familyId: string,
        childId: string | null,
        requestedByUserId: string,
      ): Promise<string> => {
        const [{ id }] = await probeDatabase
          .insert(deletionRequests)
          .values({ familyId, childId, requestedByUserId })
          .returning({ id: deletionRequests.id });
        return id;
      };

      it("refuses to delete a Child or a Family no Parent has asked to delete, writing no Audit Log entry and keeping every row, and deletes them as a confirmation once a Parent has asked, emailing no Parent (regression)", async () => {
        const adminToken = await signInWithTheHarness("admin");
        const familyA1AndA2 = [
          penTestFixtureIds.familyA1,
          penTestFixtureIds.familyA2,
        ];
        const familyA2ParentIds = [
          penTestFixtureIds.parentA2PasskeyOnly,
          penTestFixtureIds.coParentA2Invited,
        ];
        const benAndFamilyA2ChildIds = [
          penTestFixtureIds.childA1Year5,
          penTestFixtureIds.childA2Year3,
          penTestFixtureIds.childA2Year3Twin,
        ];
        const parentEmails = familyA1AndA2.flatMap(listFixtureParentEmails);
        const requestsForEither = await probeDatabase
          .select({ id: deletionRequests.id })
          .from(deletionRequests)
          .where(inArray(deletionRequests.familyId, familyA1AndA2));
        const emailsBefore = probeEmails.length;
        const deleteBenAndFamilyA2 = async () => [
          await makeAdminChange(adminToken, {
            method: "DELETE",
            url: `/api/admin/children/${penTestFixtureIds.childA1Year5}`,
          }),
          await makeAdminChange(adminToken, {
            method: "DELETE",
            url: `/api/admin/families/${penTestFixtureIds.familyA2}`,
          }),
        ];

        const unasked = await deleteBenAndFamilyA2();
        const childrenWhileUnasked = await probeDatabase
          .select({ id: children.id })
          .from(children)
          .where(inArray(children.id, benAndFamilyA2ChildIds));
        const parentsWhileUnasked = await probeDatabase
          .select({ id: users.id })
          .from(users)
          .where(inArray(users.id, familyA2ParentIds));
        await askForDeletionInProbe(
          penTestFixtureIds.familyA1,
          penTestFixtureIds.childA1Year5,
          penTestFixtureIds.parentA1,
        );
        await askForDeletionInProbe(
          penTestFixtureIds.familyA2,
          null,
          penTestFixtureIds.parentA2PasskeyOnly,
        );
        const asked = await deleteBenAndFamilyA2();

        expect(requestsForEither).toEqual([]);
        expect(unasked.map(({ change }) => change)).toEqual([
          { status: 409, actions: [] },
          { status: 409, actions: [] },
        ]);
        expect(childrenWhileUnasked).toHaveLength(3);
        expect(parentsWhileUnasked).toHaveLength(2);
        expect(asked.map(({ change }) => change)).toEqual([
          {
            status: 204,
            actions: ["child.deleted", "deletion-request.confirmed"],
          },
          {
            status: 204,
            actions: ["deletion-request.confirmed", "family.deleted"],
          },
        ]);
        expect(
          await probeDatabase
            .select({ id: children.id })
            .from(children)
            .where(inArray(children.id, benAndFamilyA2ChildIds)),
        ).toEqual([]);
        expect(
          await probeDatabase
            .select({ id: users.id })
            .from(users)
            .where(inArray(users.id, familyA2ParentIds)),
        ).toEqual([]);
        expect(
          probeEmails
            .slice(emailsBefore)
            .filter(({ to }) => parentEmails.includes(to)),
        ).toEqual([]);
      });

      it("keeps the record that the Admin opened a Child's progress once that Child is deleted, and once their whole Family is, while the Family's export still lists a Child still there (regression)", async () => {
        const adminToken = await signInWithTheHarness("admin");
        const caraId = penTestFixtureIds.childA2Year3;
        const twinId = penTestFixtureIds.childA2Year3Twin;
        const rowsBefore = await countAccessLogRowsFor(caraId);

        const opened = await injectProbeAs(adminToken, {
          method: "GET",
          url: `/api/children/${caraId}/progress`,
        });
        const twinOpened = await injectProbeAs(adminToken, {
          method: "GET",
          url: `/api/children/${twinId}/progress`,
        });
        const rowsOnceOpened = await countAccessLogRowsFor(caraId);
        const twinRowsOnceOpened = await countAccessLogRowsFor(twinId);
        await askForDeletionInProbe(
          penTestFixtureIds.familyA2,
          caraId,
          penTestFixtureIds.parentA2PasskeyOnly,
        );
        const deleted = await injectProbeAs(adminToken, {
          method: "DELETE",
          url: `/api/admin/children/${caraId}`,
        });
        const familyExport = await injectProbeAs(
          await signInWithTheHarness("parentA2PasskeyOnly"),
          { method: "GET", url: "/api/family-export" },
        );
        const exportedAccessLogChildIds = (
          new Map(Object.entries(readFamilyExport(familyExport.json()))).get(
            "adminAccessLogs",
          ) ?? []
        ).map((row) =>
          typeof row === "object" && row !== null && "childId" in row
            ? row.childId
            : undefined,
        );
        await askForDeletionInProbe(
          penTestFixtureIds.familyA2,
          null,
          penTestFixtureIds.parentA2PasskeyOnly,
        );
        const familyDeleted = await injectProbeAs(adminToken, {
          method: "DELETE",
          url: `/api/admin/families/${penTestFixtureIds.familyA2}`,
        });

        expect(
          listStatusCodes([
            opened,
            twinOpened,
            deleted,
            familyExport,
            familyDeleted,
          ]),
        ).toEqual([200, 200, 204, 200, 204]);
        expect(rowsOnceOpened).toBe(rowsBefore + 1);
        expect(exportedAccessLogChildIds).toContain(twinId);
        expect(exportedAccessLogChildIds).not.toContain(caraId);
        expect(await countAccessLogRowsFor(caraId)).toBe(rowsOnceOpened);
        expect(await countAccessLogRowsFor(twinId)).toBe(twinRowsOnceOpened);
      });

      it("keeps the record that the Admin opened a Child's progress after the Admin deletes that Child", async () => {
        const adminToken = await signInWithTheHarness("admin");
        const caraId = penTestFixtureIds.childA2Year3;
        await injectProbeAs(adminToken, {
          method: "GET",
          url: `/api/children/${caraId}/progress`,
        });
        const rowsOnceOpened = await countAccessLogRowsFor(caraId);
        // The Admin deletes a Child only on a Parent's request (#284), so Cara's Parent asks first.
        await askForDeletionInProbe(
          penTestFixtureIds.familyA2,
          caraId,
          penTestFixtureIds.parentA2PasskeyOnly,
        );

        const deleted = await injectProbeAs(adminToken, {
          method: "DELETE",
          url: `/api/admin/children/${caraId}`,
        });

        expect(deleted.statusCode).toBe(204);
        expect(await countAccessLogRowsFor(caraId)).toBe(rowsOnceOpened);
      });
    });

